"use strict";

function addBackToTop(options) {
  var settings = options || {};
  var backgroundColor = settings.backgroundColor || "#000";
  var cornerOffset = settings.cornerOffset !== undefined ? settings.cornerOffset : 20;
  var diameter = settings.diameter || 56;
  var ease = settings.ease || function (t) {
    return 0.5 * (1 - Math.cos(Math.PI * t));
  };
  var id = settings.id || "back-to-top";
  var innerHTML = settings.innerHTML || '<svg viewBox="0 0 24 24"><path d="M7.41 15.41L12 10.83l4.59 4.58L18 14l-6-6-6 6z"></path></svg>';
  var onClickScrollTo = settings.onClickScrollTo !== undefined ? settings.onClickScrollTo : 0;
  var scrollContainer = settings.scrollContainer || document.body;
  var scrollDuration = settings.scrollDuration !== undefined ? settings.scrollDuration : 100;
  var showWhenScrollTopIs = settings.showWhenScrollTopIs !== undefined ? settings.showWhenScrollTopIs : 1;
  var size = settings.size || diameter;
  var textColor = settings.textColor || "#fff";
  var zIndex = settings.zIndex !== undefined ? settings.zIndex : 1;

  var isBodyContainer = scrollContainer === document.body;
  var docEl = isBodyContainer && document.documentElement;

  // Inline CSS styles
  var svgSize = Math.round(0.35 * size);
  var svgMargin = Math.round(0.2 * size);
  var cssStyles =
    "#" + id + " {" +
      "background: " + backgroundColor + ";" +
      "border-radius: 50%;" +
      "bottom: " + cornerOffset + "px;" +
      "box-shadow: 0 2px 5px 0 rgba(0,0,0,.26);" +
      "color: " + textColor + ";" +
      "cursor: pointer;" +
      "display: block;" +
      "height: " + size + "px;" +
      "opacity: 1;" +
      "outline: 0;" +
      "position: fixed;" +
      "right: " + cornerOffset + "px;" +
      "transition: bottom .2s, opacity .2s;" +
      "user-select: none;" +
      "width: " + size + "px;" +
      "z-index: " + zIndex + ";" +
    "}" +
    "#" + id + " svg {" +
      "display: block;" +
      "fill: currentColor;" +
      "height: " + svgSize + "px;" +
      "margin: " + svgMargin + "px auto 0;" +
      "width: " + svgSize + "px;" +
    "}" +
    "#" + id + ".hidden {" +
      "bottom: -" + size + "px;" +
      "opacity: 0;" +
    "}";

  var styleElement = document.createElement("style");
  styleElement.appendChild(document.createTextNode(cssStyles));
  document.head.insertAdjacentElement("afterbegin", styleElement);

  // Smooth scroll logic
  function scrollPageTo(to) {
    if (isBodyContainer) {
      document.body.scrollTop = to;
      if (docEl) docEl.scrollTop = to;
    } else {
      scrollContainer.scrollTop = to;
    }
  }

  function getScrollPosition() {
    if (isBodyContainer) {
      return window.scrollY || window.pageYOffset || (docEl ? docEl.scrollTop : 0) || 0;
    }
    return scrollContainer.scrollTop || 0;
  }

  // Create button
  var button = document.createElement("div");
  button.id = id;
  button.className = "hidden";
  button.innerHTML = innerHTML;

  button.addEventListener("click", function (event) {
    event.preventDefault();
    var targetScrollTop = typeof onClickScrollTo === "function" ? onClickScrollTo() : onClickScrollTo;
    var perf = window.performance;
    var raf = window.requestAnimationFrame;

    if (scrollDuration <= 0 || !perf || !raf) {
      return scrollPageTo(targetScrollTop);
    }

    var startTime = perf.now();
    var startScrollTop = getScrollPosition();
    var distance = startScrollTop - targetScrollTop;

    function step(time) {
      var progress = Math.min((time - startTime) / scrollDuration, 1);
      scrollPageTo(startScrollTop - Math.round(ease(progress) * distance));
      if (progress < 1) {
        raf(step);
      }
    }
    raf(step);
  });

  document.body.appendChild(button);

  // Footer tracking elements
  var stickyFooter = document.querySelector(".sticky-bottom");
  var fixedFooter = document.querySelector(".fixed-bottom");

  var ticking = false;
  var isHidden = true;

  function update() {
    var scrollTop = getScrollPosition();
    var showButton = scrollTop >= showWhenScrollTopIs;

    var footerOffset = 0;
    if (stickyFooter) {
      var tRect = stickyFooter.getBoundingClientRect();
      if (tRect.top < window.innerHeight) {
        footerOffset = window.innerHeight - tRect.top;
      }
    } else if (fixedFooter) {
      var eRect = fixedFooter.getBoundingClientRect();
      footerOffset = eRect.height;
    }

    if (showButton) {
      if (isHidden) {
        button.className = "";
        isHidden = false;
      }
      if (stickyFooter) {
        button.style.bottom = (footerOffset > 0 ? (footerOffset + 15) : cornerOffset) + "px";
      } else if (fixedFooter) {
        button.style.bottom = (footerOffset + 15) + "px";
      } else {
        button.style.bottom = cornerOffset + "px";
      }
    } else {
      if (!isHidden) {
        button.className = "hidden";
        isHidden = true;
      }
    }

    ticking = false;
  }

  function onScrollOrResize() {
    if (!ticking) {
      window.requestAnimationFrame(update);
      ticking = true;
    }
  }

  var eventTarget = isBodyContainer ? window : scrollContainer;
  eventTarget.addEventListener("scroll", onScrollOrResize, { passive: true });
  window.addEventListener("resize", onScrollOrResize, { passive: true });

  // Update elements on window load in case they load dynamically
  window.addEventListener("load", function () {
    if (!stickyFooter) stickyFooter = document.querySelector(".sticky-bottom");
    if (!fixedFooter) fixedFooter = document.querySelector(".fixed-bottom");
    onScrollOrResize();
  });

  // Initial check on next animation frame to prevent forced reflow on page load
  window.requestAnimationFrame(update);
}
